SELECT c73, c01, c02, c64, c65, c66, c70, c71, LENGTH(c72) FROM t09 ORDER BY c73;
-- 뒤쪽 컬럼만 선택(접두 증분 deform 가 앞의 NULL 컬럼을 건너뜀)
